import { useEffect, useState } from "react";

export function useUsers() {
  const [users, setUsers] = useState([]);
  useEffect(() => {
    fetch("http://localhost:4000/users")
      .then((res) => res.json())
      .then(setUsers);
  }, []);
  return {
    users,
  };
}
